head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.secugrpId = "";       // 증권그룹ID — 목록 조회·팝업에 쓴다. 메뉴(STF05700) 고정 SW (원본 pSecuGrpId)
scwin.findSecugrpId = "";   // 회사 찾기 증권그룹ID — 진입 파라미터로 바뀔 수 있다 (원본 fr_SecuGrpId, §8 #1)
scwin.mktTpCd = "";         // 회사 시장구분 1: 유가, 2: 코스닥 (원본 vSPOT_ISU_TRD_MKT_TP_CD)
scwin.MKT_TP_KSE = "1";             // 유가증권시장
scwin.MKT_TP_KOSDAQ = "2";          // 코스닥시장
scwin.POPUP_URL = "/ui/lst/lstproc/ULDSTF05710.xml";    // 신주상장 관리 팝업 — 배포 경로 가정(§10 #5)

// 원본 : /lstproc/ULDSTF05700.gfm (신주상장 — 신주인수권증권)
/*
 * 화면 동작
 *  - [회사 찾기](ULDSTF92009_SW)로 회사를 고르면 발행예정종목(접수)과 증권발행내역을 차례로 조회한다.
 *  - 발행예정종목 행을 더블클릭하면 접수(R), 증권발행내역 행은 이력(H), [신규]는 신규(N)로 신주상장 관리 팝업(ULDSTF05710)을 연다.
 *  - 팝업이 닫히면(저장·수정·삭제·닫기 모두) 두 목록을 다시 조회한다.
 *  - 다른 화면(문서처리현황)이 회사를 넘겨 열면 그 회사로 바로 조회한다.
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF05700/ULDSTF05700.md (§번호는 이 문서의 절)
 */

// 화면 상태값

// 고정값

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 28
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05700.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 28
 * @description 로딩 — 증권그룹ID → 조회 Enter 키 바인딩 → 진입 파라미터로 회사를 받았으면 바로 조회. (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 증권그룹ID — 이 화면 메뉴(STF05700)는 업무공통 표에서 SW(신주인수권증권) 하나다
    scwin.secugrpId = $c.lc.glb.SECUGRP_ID_SW;
    scwin.findSecugrpId = scwin.secugrpId;

    // 2) 조회 영역 Enter 키(1회, 규칙 22)
    $c.win.setEnterKeyEvent(panel_Top, scwin.btn_Search_onclick);

    // 3) 진입 파라미터 — 원본 fn_GetRecvDocProvider 가 여는 화면 URL 을 위치로 잘라 gIsurCd 등에 넣던 값.
    // TODO: 키 이름은 제안값 — 문서처리현황 전환 때 맞춘다 (§10 #4)
    const param = $c.data.getParameter() ?? {};
    if ($c.util.isEmpty(param.isurCd)) return;

    dma_search.set("isurCd", String(param.isurCd));
    dma_search.set("comNm", String(param.comAbbrv ?? ""));
    scwin.findSecugrpId = String(param.secugrpId ?? "") || scwin.findSecugrpId;
    scwin.mktTpCd = String(param.mktTpCd ?? "");
    await scwin.search();    // 원본 btn_Search.onclick()
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 조회 버튼 클릭 (조회 영역 Enter 키도 이 핸들러)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05700.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.img_COM_NM_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 회사 찾기(돋보기) 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_COM_NM_onclick = async function (e) {
    try {
        await scwin.openCompanyPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05700.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_Recv_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 발행예정종목 행 더블클릭 — 접수(R)로 신주상장 관리 팝업을 연다. (원본 grd_Recv OnDblClick → fn_OpenDetailRecv)
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_Recv_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.openDetailRecv(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05700.grd_Recv_oncelldblclick" });
    }
};

/**
 * @method
 * @name scwin.grd_List_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 증권발행내역 행 더블클릭 — 이력(H)으로 신주상장 관리 팝업을 연다. (원본 grd_List OnDblClick → fn_OpenDetailMng(row))
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_List_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.openDetailHist(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05700.grd_List_oncelldblclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Excel_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 엑셀다운로드 버튼 클릭 — 증권발행내역을 내려받는다.
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Excel_onclick = async function (e) {
    try {
        scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05700.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_New_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 신규 버튼 클릭 — 신규(N)로 신주상장 관리 팝업을 연다. (원본 btn_New onclick → fn_OpenDetailMng(-1))
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_New_onclick = async function (e) {
    try {
        await scwin.openNew();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05700.btn_New_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectRecvList
 * @author Inswave
 * @date 2026. 10. 28
 * @description 발행예정종목(접수) 목록 조회 — 유가·코스닥 회사만 조회하고 상장예정일 열은 코스닥만 보인다. 그 밖의 시장이면 목록을 비운다. (원본 fn_recv_list_sync + dts_Recv OnLoadCompleted — §5.1)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectRecvList = async function () {
    if (scwin.mktTpCd !== scwin.MKT_TP_KSE && scwin.mktTpCd !== scwin.MKT_TP_KOSDAQ) {
        // 원본은 조회하지 않아 앞 회사의 목록·건수가 남았다 — 비워서 다른 회사 접수 건을 열지 않게 한다(§8 #2)
        dlt_recv.removeAll();
        $c.stf.fillGridHeaderTotalCnt(0, edt_TotalCnt_1);
        return false;
    }
    grd_Recv.setColumnVisible("listDd", scwin.mktTpCd === scwin.MKT_TP_KOSDAQ);

    const sbmOptions = {
        id : "sbm_selectRecvList",
        method : "get",
        action : "/api/listing/lstproc/warrant/listing/select-list-recv",
        target : "dlt_recv=body",
        gridview : "grd_Recv",
        isProcessMsg : false
    };

    // 원본 DIV_IDX(유가 RECV_S / 코스닥 RECV_K) 분기는 명세 spotIsuTrdMktTpCd 로 서버가 정한다(§5.1)
    const result = await $c.sbm.executeDynamic(sbmOptions, { isurCd : dma_search.get("isurCd"), spotIsuTrdMktTpCd : scwin.mktTpCd });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return false;    // 실패 안내는 공통 오류 핸들러(원본 OnLoadError → alert_error)

    $c.stf.fillGridHeaderTotalCnt(dlt_recv.getRowCount(), edt_TotalCnt_1);
    return true;
};

/**
 * @method
 * @name scwin.selectHistList
 * @author Inswave
 * @date 2026. 10. 28
 * @description 증권발행내역 목록 조회 — 건수를 적고 마지막 행에 포커스를 둔다. (원본 fn_list_sync + dts_List OnLoadCompleted — §5.2)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectHistList = async function () {
    const sbmOptions = {
        id : "sbm_selectHistList",
        method : "get",
        action : "/api/listing/lstproc/warrant/listing/select-list-hist",
        target : "dlt_hist=body",
        gridview : "grd_List",
        isProcessMsg : false
    };

    // TODO: 명세 target 은 "dma_std=body" 로 적혔으나 응답은 목록(dlt_hist) — 목록으로 받는다(§10 #3)
    const result = await $c.sbm.executeDynamic(sbmOptions, { isurCd : dma_search.get("isurCd"), secugrpId : scwin.secugrpId });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return false;    // 실패 안내는 공통 오류 핸들러(원본 OnLoadError → alert_error)

    const cnt = dlt_hist.getRowCount();
    $c.stf.fillGridHeaderTotalCnt(cnt, edt_TotalCnt_2);
    // 원본 dts_List.RowPosition = countrow — 마지막(최근) 행 선택
    if (cnt > 0) grd_List.setFocusedCell(cnt - 1, 0);
    return true;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 10. 28
 * @description 조회 — 회사를 고르지 않았으면 안내하고 멈춘다. (원본 btn_Search onclick — §6.1)
 * @returns
 * @hidden N
 */
scwin.search = async function () {
    if (!await scwin.checkCompany()) return;
    await scwin.allListSync();
};

/**
 * @method
 * @name scwin.checkCompany
 * @author Inswave
 * @date 2026. 10. 28
 * @description 회사 선택 여부 검사 — 없으면 "[회사]를 선택하세요." 안내 후 회사코드에 포커스. (원본 btn_Search·btn_New onclick 앞부분 — §6.1)
 * @returns {Promise<Boolean>} 회사를 골랐으면 true
 * @hidden N
 */
scwin.checkCompany = async function () {
    if (!$c.util.isEmpty(dma_search.get("isurCd"))) return true;

    await $c.win.alert("[회사]를 선택하세요.");
    txb_ISUR_CD.focus();
    return false;
};

/**
 * @method
 * @name scwin.allListSync
 * @author Inswave
 * @date 2026. 10. 28
 * @description 두 목록 조회 — 먼저 두 목록·건수를 비우고 발행예정종목 → 증권발행내역 순서로 조회(원본 동기 조회 순서 유지). (원본 fn_all_list_sync — §6.2)
 * @returns
 * @hidden N
 */
scwin.allListSync = async function () {
    // 조회가 실패·건너뜀이어도 앞 회사의 행이 남아 다른 회사 건으로 팝업을 열지 않게 먼저 비운다(§8 #11)
    dlt_recv.removeAll();
    dlt_hist.removeAll();
    $c.stf.fillGridHeaderTotalCnt(0, edt_TotalCnt_1);
    $c.stf.fillGridHeaderTotalCnt(0, edt_TotalCnt_2);

    await scwin.selectRecvList();
    await scwin.selectHistList();
};

/**
 * @method
 * @name scwin.openCompanyPopup
 * @author Inswave
 * @date 2026. 10. 28
 * @description 회사 찾기(ULDSTF92009_SW, 신주상장 "1"). 고른 회사를 조회 영역에 넣고 두 목록을 조회한다. 취소·닫기면 아무것도 하지 않는다.
 * (원본 img_COM_NM onclick + fn_GetParIsur/fn_SetParIsur + fn_PopFindCorpChrgSW — §6.3)
 * @returns
 * @hidden N
 */
scwin.openCompanyPopup = async function () {
    // 92009_SW 는 행을 더블클릭했을 때만 DBCLICKYN "Y" 와 회사를 돌려준다. 취소·닫기(X)는 { isCloseButtonClick } 객체다.
    const res = await $c.lc.popFindCorpChrgSW(scwin.findSecugrpId, "1");
    if (res?.DBCLICKYN !== "Y" || $c.util.isEmpty(res?.ISUR_CD)) return;

    dma_search.set("isurCd", String(res.ISUR_CD));
    dma_search.set("comNm", String(res.COM_NM ?? ""));
    scwin.mktTpCd = String(res.SPOT_ISU_TRD_MKT_TP_CD ?? "");
    await scwin.allListSync();
};

/**
 * @method
 * @name scwin.openNew
 * @author Inswave
 * @date 2026. 10. 28
 * @description 신규 — 회사를 골랐으면 신규(N)로 관리 팝업을 연다. (원본 btn_New onclick + fn_OpenDetailMng(-1) — §6.4)
 * @returns
 * @hidden N
 */
scwin.openNew = async function () {
    if (!await scwin.checkCompany()) return;
    await scwin.openDetailPopup("N", "", "", null);
};

/**
 * @method
 * @name scwin.openDetailRecv
 * @author Inswave
 * @date 2026. 10. 28
 * @description 접수 행 열기 — 접수번호가 있는 행만 접수(R)로 관리 팝업을 연다(행 전체를 recv 로 넘김). (원본 fn_OpenDetailRecv — §6.4)
 * @param {Number} rowIndex 발행예정종목 행 인덱스(화면 번호)
 * @returns
 * @hidden N
 */
scwin.openDetailRecv = async function (rowIndex) {
    const acptNo = String(dlt_recv.getCellData(rowIndex, "acptNo") ?? "");
    if ($c.util.isEmpty(acptNo)) return;    // 원본도 접수번호가 없으면 열지 않는다

    const bzProcsNo = String(dlt_recv.getCellData(rowIndex, "bzProcsNo") ?? "");
    await scwin.openDetailPopup("R", bzProcsNo, acptNo, dlt_recv.getRowJSON(rowIndex));
};

/**
 * @method
 * @name scwin.openDetailHist
 * @author Inswave
 * @date 2026. 10. 28
 * @description 이력 행 열기 — 그 행의 업무처리번호로 이력(H) 관리 팝업을 연다. (원본 fn_OpenDetailMng(row) + fn_setBzProcsNo — §6.4)
 * @param {Number} rowIndex 증권발행내역 행 인덱스(화면 번호)
 * @returns
 * @hidden N
 */
scwin.openDetailHist = async function (rowIndex) {
    const bzProcsNo = String(dlt_hist.getCellData(rowIndex, "bzProcsNo") ?? "");
    await scwin.openDetailPopup("H", bzProcsNo, "", null);
};

/**
 * @method
 * @name scwin.openDetailPopup
 * @author Inswave
 * @date 2026. 10. 28
 * @description 신주상장 관리 팝업(ULDSTF05710)을 열고 닫힐 때까지 기다린 뒤 두 목록을 다시 조회한다.
 * 팝업은 $c.data.getParameter() 로 받는다 — 키는 ULDSTF05710 결과서 §1.2 계약. (원본 fn_OpenPopup + 팝업의 부모 전역 직접 참조·parent.fn_all_list_sync — §6.5)
 * @param {String} openTyp 여는 방식 R: 접수, H: 이력, N: 신규
 * @param {String} bzProcsNo 업무처리번호 (N 은 "")
 * @param {String} acptNo 접수번호 (R 만)
 * @param {Object} recv 접수 행 (R 만, 그 밖은 null)
 * @returns
 * @hidden N
 */
scwin.openDetailPopup = async function (openTyp, bzProcsNo, acptNo, recv) {
    const data = {
        openTyp : openTyp,
        bzProcsNo : bzProcsNo,
        acptNo : acptNo,
        isurCd : dma_search.get("isurCd"),
        secugrpId : scwin.secugrpId,
        spotIsuTrdMktTpCd : scwin.mktTpCd,
        recv : recv
    };
    await $c.win.openPopup(scwin.POPUP_URL,
        { id : "ULDSTF05710", popupName : "신주인수권증권 신주상장 관리", width : 860, height : 490, type : "pageFramePopup" }, data);

    // 원본은 팝업이 저장·수정·삭제 성공 때마다 parent.fn_all_list_sync() — TO-BE 는 닫힌 뒤 부모가 재조회(§8 #5)
    await scwin.allListSync();
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 28
 * @description 증권발행내역을 엑셀로 내려받는다. 0건 안내는 공통 함수가 한다. (원본 btn_Excel onclick — §6.6)
 * @returns
 * @hidden N
 */
scwin.excelDown = function () {
    // TODO: 원본 GridToExcel(…, "", "8") 옵션(숨김 열 포함 여부 등) 확인 (§10 #6)
    $c.data.downloadGridViewExcel(grd_List, {
        // 파일명 {menuId}_{이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42)
        fileName : $c.win.getProgramId() + "_신주인수권증권 발행내역_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx",
        sheetName : "sheet1"
    });
};
